static ll maxll(ll a, ll b) { return a > b ? a : b; }
static ll minll(ll a, ll b) { return a < b ? a : b; }
static ll llabs2(ll x) { return x >= 0 ? x : -x; }

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Edge *edges = (Edge *)malloc(sizeof(Edge) * 2 * (N - 1));
    int *head = (int *)malloc(sizeof(int) * (N + 1));
    for (int i = 1; i <= N; i++) head[i] = -1;

