    for (int i = 0; i < N - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        edges[ecnt].to = b;
        edges[ecnt].next = head[a];
        head[a] = ecnt++;

        edges[ecnt].to = a;
        edges[ecnt].next = head[b];
        head[b] = ecnt++;
    }

    int K;
    scanf("%d", &K);

    ll *known = (ll *)malloc(sizeof(ll) * (N + 1));
    int *fixed = (int *)malloc(sizeof(int) * (N + 1));
    for (int i = 1; i <= N; i++) {
        fixed[i] = 0;
        known[i] = 0;
    }

    for (int i = 0; i < K; i++) {
        int v;
        ll p;
        scanf("%d %lld", &v, &p);
        fixed[v] = 1;
        known[v] = p;
    }

    /* Root tree at 1 */
    int *parent = (int *)malloc(sizeof(int) * (N + 1));
    int *order = (int *)malloc(sizeof(int) * N);
    int *stack = (int *)malloc(sizeof(int) * N);
    int top = 0, ordsz = 0;

    parent[1] = 0;
    stack[top++] = 1;
    while (top) {
        int v = stack[--top];
        order[ordsz++] = v;
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int u = edges[e].to;
            if (u == parent[v]) continue;
            parent[u] = v;
            stack[top++] = u;
        }
    }

    /* For each vertex, possible interval [L,R] and required parity par */
    ll *L = (ll *)malloc(sizeof(ll) * (N + 1));
    ll *R = (ll *)malloc(sizeof(ll) * (N + 1));
    int *par = (int *)malloc(sizeof(int) * (N + 1)); /* 0 even, 1 odd */

    for (int i = 1; i <= N; i++) {
        if (fixed[i]) {
            L[i] = R[i] = known[i];
            par[i] = (int)((known[i] % 2 + 2) % 2);
        } else {
            L[i] = -INF;
            R[i] = INF;
            par[i] = -1; /* unknown */
        }
    }

    /* Bottom-up merge children constraints */
    for (int idx = N - 1; idx >= 0; idx--) {
        int v = order[idx];

        ll low = L[v], high = R[v];
        int p = par[v];

        for (int e = head[v]; e != -1; e = edges[e].next) {
            int u = edges[e].to;
            if (u == parent[v]) continue;

            /* Parent value x must allow child in [L[u],R[u]] with diff 1
               => x in [L[u]-1, R[u]+1], and parity opposite to child parity.
            */
            ll cl = L[u] - 1;
            ll cr = R[u] + 1;
            low = maxll(low, cl);
            high = minll(high, cr);

            int needp = par[u] ^ 1;
            if (p == -1) p = needp;
            else if (p != needp) {
                printf("No\n");
                return 0;
            }
        }

        if (low > high) {
            printf("No\n");
            return 0;
        }

        /* Need some value in [low,high] with parity p */
        if (p != -1) {
            ll cand = low;
            if (((cand % 2 + 2) % 2) != p) cand++;
            if (cand > high) {
                printf("No\n");
                return 0;
            }
        }

        L[v] = low;
        R[v] = high;
        par[v] = p;
    }

    /* If root parity still unknown, choose arbitrary */
    if (par[1] == -1) par[1] = 0;

    /* Choose root value */
    ll rootVal = L[1];
    if (((rootVal % 2 + 2) % 2) != par[1]) rootVal++;
    if (rootVal > R[1]) {
        printf("No\n");
        return 0;
    }

    ll *ans = (ll *)malloc(sizeof(ll) * (N + 1));
    ans[1] = rootVal;

    /* Top-down construct values */
    top = 0;
    stack[top++] = 1;
    while (top) {
        int v = stack[--top];
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int u = edges[e].to;
            if (u == parent[v]) continue;

            ll a = ans[v] - 1;
            ll b = ans[v] + 1;
            int ok = 0;

            if (a >= L[u] && a <= R[u] && (((a % 2 + 2) % 2) == par[u])) {
                ans[u] = a;
                ok = 1;
            } else if (b >= L[u] && b <= R[u] && (((b % 2 + 2) % 2) == par[u])) {
                ans[u] = b;
                ok = 1;
            }

            if (!ok) {
                printf("No\n");
                return 0;
            }
            stack[top++] = u;
        }
    }

    /* Final verification for fixed nodes */
    for (int i = 1; i <= N; i++) {
        if (fixed[i] && ans[i] != known[i]) {
            printf("No\n");
            return 0;
        }
    }

    printf("Yes\n");
    for (int i = 1; i <= N; i++) {
        printf("%lld\n", ans[i]);
    }

    return 0;
}

