    for (int i = 0; i < N - 1; ++i) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    int K;
    cin >> K;

    const int64 INF = (1LL << 60);

    vector<int64> L(N + 1, -INF), R(N + 1, INF);
    vector<int> fixed(N + 1, 0);
    for (int i = 0; i < K; ++i) {
        int v;
        int64 p;
        cin >> v >> p;
        fixed[v] = 1;
        L[v] = R[v] = p;
    }

    // Root the tree
    int root = 1;
    vector<int> parent(N + 1, -1), order;
    order.reserve(N);
    queue<int> q;
    q.push(root);
    parent[root] = 0;
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        order.push_back(v);
        for (int to : g[v]) {
            if (parent[to] == -1) {
                parent[to] = v;
                q.push(to);
            }
        }
    }

    // Bottom-up: collect constraints from children.
    for (int i = N - 1; i >= 0; --i) {
        int v = order[i];
        for (int to : g[v]) {
            if (to == parent[v]) continue;
            // If child is in [L[to], R[to]], then parent must be in [L[to]-1, R[to]+1]
            L[v] = max(L[v], L[to] - 1);
            R[v] = min(R[v], R[to] + 1);
        }
        if (L[v] > R[v]) {
            cout << "No\n";
            return 0;
        }
    }

    // Top-down: add parent constraints and parity constraints.
    // Since adjacent values differ by exactly 1, parity flips on every edge.
    // Therefore all possible values at a node have the same parity:
    // value parity = (root parity) xor depth parity.
    vector<int> depth(N + 1, 0);
    for (int v : order) {
        for (int to : g[v]) {
            if (to == parent[v]) continue;
            depth[to] = depth[v] + 1;
        }
    }

    // Root interval currently [L[root], R[root]].
    // Need at least one integer with one parity.
    auto hasParity = [&](int64 l, int64 r, int p) -> bool {
        if (l > r) return false;
        int64 x = l;
        if (((x & 1LL) + 2) % 2 != p) ++x;
        return x <= r;
    };

    int rootParity = -1;
    if (hasParity(L[root], R[root], 0)) rootParity = 0;
    if (rootParity == -1 && hasParity(L[root], R[root], 1)) rootParity = 1;
    if (rootParity == -1) {
        cout << "No\n";
        return 0;
    }

    // Fix root to any valid value with chosen parity.
    int64 rootVal = L[root];
    if (((rootVal & 1LL) + 2) % 2 != rootParity) ++rootVal;
    if (rootVal > R[root]) {
        cout << "No\n";
        return 0;
    }

    vector<int64> ans(N + 1, 0);
    ans[root] = rootVal;

    // Propagate actual values downward.
    for (int v : order) {
        for (int to : g[v]) {
            if (to == parent[v]) continue;

            // Child must be ans[v] +/- 1 and also lie in [L[to], R[to]].
            int64 a = ans[v] - 1;
            int64 b = ans[v] + 1;

            bool okA = (L[to] <= a && a <= R[to]);
            bool okB = (L[to] <= b && b <= R[to]);

            if (!okA && !okB) {
                cout << "No\n";
                return 0;
            }

            // Choose any valid one.
            ans[to] = okA ? a : b;
        }
    }

    // Final verification for fixed vertices and edges.
    for (int v = 1; v <= N; ++v) {
        if (fixed[v] && ans[v] != L[v]) {
            cout << "No\n";
            return 0;
        }
        for (int to : g[v]) {
            if (to > v) {
                if (llabs(ans[v] - ans[to]) != 1) {
                    cout << "No\n";
                    return 0;
                }
            }
        }
    }

    cout << "Yes\n";
    for (int i = 1; i <= N; ++i) {
        cout << ans[i] << "\n";
    }

    return 0;
}

