            StringBuilder sb = new StringBuilder();
            sb.append("Yes\n");
            for (int i = 1; i <= N; i++) sb.append(ans[i]).append('\n');
            System.out.print(sb.toString());
            return;
        }

        // Multi-source propagation of lower bounds:
        // x[u] >= p - dist(source,u)
        while (!pq.isEmpty()) {
            NodeVal cur = pq.poll();
            long val = cur.val;
            int v = cur.v;

            if (val >= 0) {
                if (val < low[v]) continue;
                for (int to : g[v]) {
                    long nv = val - 1;
                    if (nv > low[to]) {
                        low[to] = nv;
                        pq.add(new NodeVal(nv, to));
                    }
                }
            } else {
                long real = -val;
                if (real > high[v]) continue;
                for (int to : g[v]) {
                    long nh = real + 1;
                    if (nh < high[to]) {
                        high[to] = nh;
                        pq.add(new NodeVal(-nh, to));
                    }
                }
            }
        }

        // Immediate interval feasibility + parity feasibility
        for (int v = 1; v <= N; v++) {
            if (low[v] > high[v]) {
                System.out.println("No");
                return;
            }
        }

        // Tree traversal to assign values.
        long[] ans = new long[N + 1];
        boolean[] vis = new boolean[N + 1];
        ArrayDeque<Integer> order = new ArrayDeque<>();
        int[] parent = new int[N + 1];
        Arrays.fill(parent, -1);

        // Start from any fixed node
        int root = -1;
        for (int i = 1; i <= N; i++) {
            if (fixed[i]) {
                root = i;
                break;
            }
        }

        // Build parent/order
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(root);
        vis[root] = true;
        parent[root] = 0;
        while (!q.isEmpty()) {
            int v = q.poll();
            order.add(v);
            for (int to : g[v]) {
                if (!vis[to]) {
                    vis[to] = true;
                    parent[to] = v;
                    q.add(to);
                }
            }
        }

        // Assign root
        ans[root] = fixedVal[root];

        // BFS assignment:
        // for child, choose ans[parent] +/- 1 that lies in [low[child], high[child]]
        while (!order.isEmpty()) {
            int v = order.poll();
            for (int to : g[v]) {
                if (to == parent[v]) continue;

                long a = ans[v] - 1;
                long b = ans[v] + 1;

                boolean okA = (low[to] <= a && a <= high[to]);
                boolean okB = (low[to] <= b && b <= high[to]);

                if (!okA && !okB) {
                    System.out.println("No");
                    return;
                }

                if (okA && okB) {
                    // Prefer fixed value if needed, otherwise any.
                    if (fixed[to]) {
                        if (fixedVal[to] == a) ans[to] = a;
                        else if (fixedVal[to] == b) ans[to] = b;
                        else {
                            System.out.println("No");
                            return;
                        }
                    } else {
                        ans[to] = a;
                    }
                } else if (okA) {
                    ans[to] = a;
                } else {
                    ans[to] = b;
                }
            }
        }

        // Final verification
        for (int v = 1; v <= N; v++) {
            if (fixed[v] && ans[v] != fixedVal[v]) {
                System.out.println("No");
                return;
            }
        }
        for (int v = 1; v <= N; v++) {
            for (int to : g[v]) {
                if (v < to && Math.abs(ans[v] - ans[to]) != 1) {
                    System.out.println("No");
                    return;
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append("Yes\n");
        for (int i = 1; i <= N; i++) {
            sb.append(ans[i]).append('\n');
        }
        System.out.print(sb.toString());
    }
}

import sys
from collections import deque

input = sys.stdin.readline

n = int(input())
g = [[] for _ in range(n)]
for _ in range(n - 1):
    a, b = map(int, input().split())
    a -= 1
    b -= 1
    g[a].append(b)
    g[b].append(a)

k = int(input())
val = [None] * n
for _ in range(k):
    v, p = map(int, input().split())
    v -= 1
    val[v] = p

# BFS to propagate values
q = deque()
for i in range(n):
    if val[i] is not None:
        q.append(i)

while q:
    u = q.popleft()
    for w in g[u]:
        if val[w] is None:
            val[w] = val[u] + 1 if val[u] + 1 not in (val.get(v) for v in g[w] if val[v] is not None) else val[u] - 1
            # Actually, simpler: neighbor must be val[u] ± 1
            for cand in (val[u] + 1, val[u] - 1):
                possible = True
                for v in g[w]:
                    if val[v] is not None and abs(val[v] - cand) != 1:
                        possible = False
                        break
                if possible:
                    val[w] = cand
                    q.append(w)
                    break
            else:
                print("No")
                sys.exit()
        else:
            if abs(val[w] - val[u]) != 1:
                print("No")
                sys.exit()

# If any vertex still None (disconnected component without initial value), set arbitrarily to 1
for i in range(n):
    if val[i] is None:
        val[i] = 1
        q.append(i)
        while q:
            u = q.popleft()
            for w in g[u]:
                if val[w] is None:
                    val[w] = val[u] + 1
                    q.append(w)

print("Yes")
print("\n".join(str(x) for x in val))
